const entrada = $json.body ?? $json;

const assunto = String(entrada.assunto ?? '').trim();
const mensagem = String(entrada.mensagem ?? '').trim();
const nome = String(entrada.nome ?? 'Não informado').trim();
const email = String(entrada.email ?? 'Não informado').trim();

if (!assunto || !mensagem) {
  throw new Error('Os campos "assunto" e "mensagem" são obrigatórios.');
}

return [{
  json: {
    nome,
    email,
    assunto,
    mensagem,
    recebidoEm: new Date().toISOString()
  }
}];

const original = $('Validar e organizar dados').first().json;

if ($json.error || !$json.choices?.[0]?.message?.content) {
  return [{
    json: {
      sucesso: false,
      mensagem: 'Não foi possível concluir a triagem automática. Encaminhe a solicitação para análise manual.',
      solicitacao: original,
      erro: $json.error?.message ?? 'Resposta inesperada do serviço de IA.'
    }
  }];
}

let classificacao;
try {
  classificacao = JSON.parse($json.choices[0].message.content);
} catch (e) {
  return [{
    json: {
      sucesso: false,
      mensagem: 'A IA retornou um formato que não pôde ser interpretado. Encaminhe para análise manual.',
      solicitacao: original
    }
  }];
}

return [{
  json: {
    sucesso: true,
    solicitacao: original,
    triagem: {
      categoria: classificacao.categoria ?? 'outros',
      prioridade: classificacao.prioridade ?? 'média',
      resumo: classificacao.resumo ?? '',
      justificativa: classificacao.justificativa ?? '',
      resposta_sugerida: classificacao.resposta_sugerida ?? ''
    },
    observacao: 'Classificação automática sugerida por IA. Revise antes de tomar decisões ou responder ao solicitante.'
  }
}];
